CREATE TABLE IF NOT EXISTS agent_updates (server_id varchar(36) PRIMARY KEY, request_id varchar(36) NOT NULL DEFAULT '', credential_hash varchar(64) NOT NULL DEFAULT '', status varchar(16) NOT NULL DEFAULT 'idle', target_version varchar(32) NOT NULL DEFAULT '', updater_seen_at timestamptz, expires_at timestamptz, message varchar(256) NOT NULL DEFAULT '', FOREIGN KEY(server_id) REFERENCES servers(id));
